const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({summary:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',problems:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Z"/><path d="M9 3v16M15 5v16"/>',tasks:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 2h6v4H9zM9 11l2 2 4-4M9 17h6"/>',decisions:'<path d="M4 20V10m8 10V4m8 16v-7M2 20h20"/>',meeting:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 2v4m8-4v4M4 9h16M8 13h3m-3 4h8"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 6a8 8 0 0 1 13 3M5 15a8 8 0 0 0 13 3"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',logout:'<path d="M9 4H4v16h5m3-8h9m-4-4 4 4-4 4"/>',watch:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',alert:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v4m0 4h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',inbox:'<path d="M4 4h16l2 12v5H2v-5L4 4Z"/><path d="M2 16h6l2 3h4l2-3h6"/>',print:'<path d="M7 8V3h10v5M7 17H3V9h18v8h-4M7 14h10v7H7z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'})[name] || '<circle cx="12" cy="12" r="8"/>'}</svg>`;
const brand = () => `<a class="brand" href="/akim.html"><span class="brand-mark"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M6 25 16 6l10 19M11 18h10" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span>ASCENSION<small>${t('cityLab')}</small></span></a>`;
const language = () => `<div class="language" role="group" aria-label="Language / Тіл"><button data-action="language" data-lang="ru" aria-pressed="${lang==='ru'}">РУС</button><button data-action="language" data-lang="kk" aria-pressed="${lang==='kk'}">ҚАЗ</button></div>`;
const privileged = () => ['admin','akim'].includes(user?.role);
const canReport = task => privileged() || task.assignee === user?.login;
const localDate = value => { if (!value) return ''; const date = new Date(value); if (!Number.isFinite(date.getTime())) return ''; return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Almaty',year:'numeric',month:'2-digit',day:'2-digit'}).format(date); };
const formatDate = (value, time=false) => { if (!value) return '—'; const date = new Date(value.length===10 ? `${value}T12:00:00+05:00` : value); if (!Number.isFinite(date.getTime())) return '—'; return new Intl.DateTimeFormat(lang==='kk'?'kk-KZ':'ru-RU',{timeZone:'Asia/Almaty',day:'numeric',month:'short',year:'numeric',...(time?{hour:'2-digit',minute:'2-digit'}:{})}).format(date); };
const isOverdue = task => task.status !== 'verified' && task.dueDate < state.today;
const openComplaint = item => !['resolved','rejected'].includes(item.status);
const complaintById = id => state?.complaints.find(c => c.id===Number(id));
const taskById = id => state?.tasks.find(task => task.id===Number(id));
const groupById = id => state?.groups.find(g => g.id===Number(id));
const districtName = id => { const district = state?.districts.find(d=>d.id===id); if (!district) return t('noDistrict'); return (lang==='kk' && (district.nameKk||district.name_kk||({esil:'Есіл',almaty:'Алматы',saryarka:'Сарыарқа',baikonur:'Байқоңыр',nura:'Нұра'})[id])) || district.name || district.id; };
const button = (text,action,attributes='',secondary=false) => `<button type="button" class="button${secondary?' secondary':''}" data-action="${action}" ${attributes}>${text}</button>`;
const empty = (title,description,action='') => `<div class="empty">${icon('inbox')}<h3>${e(title)}</h3><p>${e(description)}</p>${action}</div>`;
const badge = (label,style='') => `<span class="badge ${style}">${e(label)}</span>`;
const taskStatus = task => badge(t(task.status),task.status==='reported'?'amber':task.status==='verified'?'':'gray');
const complaintStatus = item => badge(t(`complaint_${item.status}`),'gray');
function announce(message) { $('#announcer').textContent=message; }
function toast(message) { const el=$('#toast'); el.textContent=message; el.hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>{el.hidden=true;},4200); announce(message); }
async function request(path,options={}) {
  let response; const controller=new AbortController(); const timeout=setTimeout(()=>controller.abort(),15000); const signal=options.signal ? AbortSignal.any([controller.signal,options.signal]) : controller.signal;
  try { response=await fetch(path,{credentials:'same-origin',...options,signal,headers:{'x-desk-request':'1',...(options.body!==undefined?{'Content-Type':'application/json'}:{}),...options.headers},...(options.body!==undefined?{body:typeof options.body==='string'?options.body:JSON.stringify(options.body)}:{})}); }
  catch { clearTimeout(timeout);throw new Error(t('offline')); }
  let result; try { result=await response.json(); } catch { throw new Error(t('networkError')); } finally {clearTimeout(timeout);}
  if (!response.ok) {
    const error=Object.assign(new Error(result.message||t('unknownError')),{status:response.status,code:result.code});
    if (response.status===401 && !path.endsWith('/login')) { error.message=t('sessionExpired'); showLogin(true); }
    if (response.status===409 && (!result.code||result.code==='VERSION_CONFLICT')) error.message=t('stale');
    throw error;
  }
  return result;
}
function onError(error) { errorMessage=error.message||String(error); const el=$('#page-error'); if(el){el.innerHTML=`<span>${e(errorMessage)}</span>${button(t('retry'),'refresh','','true')}`;el.hidden=false;} announce(errorMessage); }
async function refresh({silent=false}={}) {
  if(refreshBusy)return; refreshBusy=true;
  const el=$('[data-action="refresh"]'); if(el)el.disabled=true;
  try {
    const next=await request('/api/desk/akim/state'); state={...next,user}; prefs={...prefs,...next.preferences}; lang=prefs.lang==='kk'?'kk':'ru'; localStorage.setItem('akim.lang',lang);
    errorMessage=''; render(); if(pendingTaskId){const id=Number(pendingTaskId);pendingTaskId=null;const current=new URL(location.href);current.searchParams.delete('task');history.replaceState(null,'',current.pathname+current.search+current.hash);if(taskById(id))showTask(id);else onError(new Error(lang==='kk'?'Тапсырма табылмады.':'Поручение не найдено.'));} if(pendingComplaintId){const id=Number(pendingComplaintId);pendingComplaintId=null;const current=new URL(location.href);current.searchParams.delete('complaint');history.replaceState(null,'',current.pathname+current.search+current.hash);if(complaintById(id))showComplaint(id);else onError(new Error(t('missingComplaint')));} if(!silent)toast(t('refreshDone'));
  } catch(error) { if(!state&&!loginDialog.open)app.innerHTML=`<div class="boot"><div><p>${e(error.message)}</p>${button(t('retry'),'refresh','',true)}</div></div>`;else onError(error); } finally {refreshBusy=false;const btn=$('[data-action="refresh"]');if(btn)btn.disabled=false;}
}
let preferenceChain=Promise.resolve();
function savePreferences(patch) {
  prefs={...prefs,...patch};
  preferenceChain=preferenceChain.then(()=>request('/api/desk/akim/preferences',{method:'PATCH',body:patch})).catch(onError);
  return preferenceChain;
}
function showLogin(recovery=false) {
  const form=`<div class="login-card"><div class="eyebrow">ASCENSION · ${t('cabinet')}</div><h2 id="login-title">${t(configured?'signIn':'accountMissing')}</h2><p>${t(recovery?'sessionExpired':'signInHint')}</p>${configured?`<form id="login-form"><div class="form-error" role="alert" hidden></div><label class="field">${t('login')}<input name="login" autocomplete="username" maxlength="80" required value="${e(user?.login||'')}"></label><label class="field">${t('password')}<input name="password" type="password" autocomplete="current-password" maxlength="200" required></label><button class="button" type="submit">${t('signIn')}${icon('arrow')}</button></form>`:`<div class="hint">${t('setupHint')}</div>${button(t('refresh'),'reload')}`}<div class="hint">${t('demoOnly')}<br>${t('dataNote')}</div><p style="margin-top:20px"><a href="/">${t('backSimulator')}</a></p></div>`;
  if(recovery){loginDialog.innerHTML=`<div class="dialog-content">${form}</div>`;if(!loginDialog.open)loginDialog.showModal();}
  else app.innerHTML=`<div class="login-shell"><section class="login-brand">${brand()}<div><h1>${t('loginHero')}<br><span>${t('loginHeroAccent')}</span></h1><p>${t('loginHeroText')}</p></div><span class="caption">ASCENSION / HACKALEM 2026</span></section><section class="login-area">${language()}${form}</section></div>`;
  document.documentElement.lang=lang;
  $('#login-form',recovery?loginDialog:app)?.addEventListener('submit', async event=>{
    event.preventDefault();const f=event.currentTarget,submit=$('button[type=submit]',f),error=$('.form-error',f);submit.disabled=true;error.hidden=true;
    try { const result=await request('/api/desk/login',{method:'POST',body:Object.fromEntries(new FormData(f))});if(user&&user.login!==result.user.login){dialog.close();selected.clear();meetingReport=null;clearDecisionDrafts();}user=result.user;if(loginDialog.open)loginDialog.close();await refresh({silent:true}); }
    catch(err){error.textContent=err.message;error.hidden=false;}
    finally{submit.disabled=false;}
  });
}
function setTab(value) { tab=value;history.replaceState(null,'',`#${tab}`);render();$('#page-title')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'}); }
function render() {
  if(!state)return;
  document.documentElement.lang=lang;document.title=`${t('cabinet')} · Ascension`;$('.skip').textContent=t('content');
  app.innerHTML=`<div class="layout"><aside class="sidebar" aria-label="${t('nav')}">${brand()}<div class="nav-caption">${t('workspace')}</div><nav class="nav">${['summary','problems','tasks','decisions','meeting'].map(key=>`<button data-action="tab" data-tab="${key}" ${tab===key?'aria-current="page"':''}>${icon(key)}<span>${t(key)}</span></button>`).join('')}</nav><div class="sidebar-bottom"><svg class="side-illustration" viewBox="0 0 170 64" fill="none" aria-hidden="true"><path d="M1 63h168M12 63V32h23v31m10 0V12h23v51m15 0V29h25v34m16 0V20h30v43M52 12V2h9v10m71 8V9h13v11" stroke="currentColor" stroke-width="1.5"/><path d="M90 63 95 10l6 53m-6-53V2m34 30h20m-20 10h20" stroke="currentColor"/></svg><span class="live-dot"></span>${t('demoOnly')}<a href="/desk.html">${t('desk')} ↗</a><a href="/">${t('simulator')} ↗</a></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${t('lab')}<span>/</span><strong>${t('cabinet')}</strong></div><div class="top-actions">${language()}<div class="user-chip"><span class="avatar">${e(user.login.slice(0,1).toUpperCase())}</span><span>${e(user.login)}<small>${t(user.role)}</small></span></div><button class="icon-button" data-action="logout" aria-label="${t('logout')}" title="${t('logout')}">${icon('logout')}</button></div></header><main id="content" class="content"><div class="hero"><div><div class="eyebrow">${tab==='summary'?t('summaryEyebrow'):`0${['summary','problems','tasks','decisions','meeting'].indexOf(tab)+1} / ${t(tab)}`}</div><h1 id="page-title" tabindex="-1">${tab==='summary'?t('cabinet'):t(tab)}</h1><p>${t(tab==='summary'?'todaySubtitle':`${tab}Subtitle`)}</p></div><div class="hero-actions">${button(`${icon('refresh')}${t('refresh')}`,'refresh','',true)}<span class="updated">${t('updated')} ${e(formatDate(state.now,true))}</span></div></div><div id="page-error" class="page-error" role="alert" ${errorMessage?'':'hidden'}>${e(errorMessage)}${button(t('retry'),'refresh','',true)}</div><div id="view"></div><footer class="data-note"><span><span class="live-dot"></span>${t('dataNote')}</span><span class="footer-links"><a href="/desk.html">${t('desk')}</a><a href="/">${t('simulator')}</a></span></footer></main></div></div>`;
  renderView();
}
function renderView(){
  const container=$('#view');if(!container)return;
  if(tab==='summary')container.innerHTML=renderSummary();
  if(tab==='problems')container.innerHTML=renderProblems();
  if(tab==='tasks')container.innerHTML=renderTasks();
  if(tab==='meeting'){container.innerHTML=renderMeeting();bindMeeting();}
  if(tab==='decisions'){container.innerHTML='<section id="akim-decisions"></section>';Promise.resolve(renderDecisions({container:$('#akim-decisions'),state:{...state,user},lang,request,onError})).catch(onError);}
}
function metric(label,value,note,kind,view,filter){return `<button class="metric ${kind}" data-action="drilldown" data-tab="${view}" data-filter="${filter}"><span class="metric-label">${t(label)}${icon(kind==='danger'?'clock':kind==='warning'?'alert':kind==='attention'?'check':'inbox')}</span><div class="metric-value">${value}</div><span class="metric-note">${t(note)}<span aria-hidden="true">↗</span></span></button>`;}
function steps(task){const index=['assigned','reported','verified'].indexOf(task.status);return `<ol class="progress-steps">${['stepAssigned','stepReported','stepVerified'].map((key,i)=>`<li class="${i<=index?'done':''}">${t(key)}</li>`).join('')}</ol>`;}
function taskRow(task){return `<div class="row"><span class="row-number">#${task.id}</span><div class="row-body"><button class="row-link" data-action="task-detail" data-id="${task.id}">${e(task.title)}</button><p>${e(task.assignee)} · ${t('deadline')}: ${e(formatDate(task.dueDate))}</p><div class="chips">${taskStatus(task)}${isOverdue(task)?badge(t('overdue'),'red'):''}${task.watchers?.includes(user.login)?badge(t('watched')):''}</div></div><button class="icon-button" data-action="task-detail" data-id="${task.id}" aria-label="${t('viewTask')} #${task.id}">${icon('arrow')}</button></div>`;}
function districtMap(){const districts=[...state.districts,...(state.complaints.some(c=>!c.districtId)?[{id:'none',name:t('noDistrict')}]:[])];return `<div class="district-map" aria-label="${t('districtOverview')}">${districts.map(d=>{const list=state.complaints.filter(c=>(d.id==='none'?!c.districtId:c.districtId===d.id)&&openComplaint(c));const high=list.filter(c=>c.priority==='high').length;return `<button class="district-tile ${high?'hot':''}" data-action="district" data-district="${e(d.id)}" aria-pressed="${prefs.districtId===d.id}" aria-label="${e(d.id==='none'?t('noDistrict'):districtName(d.id))}: ${list.length} ${t('openCount')}, ${high} ${t('highCount')}"><strong>${e(d.id==='none'?t('noDistrict'):districtName(d.id))}</strong><b>${list.length}</b><span>${t('openCount')}${high?` · ${high} !`:''}</span><i aria-hidden="true">↗</i></button>`;}).join('')}</div><p class="map-caption"><span class="map-key">${t('urgent')}</span><br>${t('schematic')}</p>`;}
function renderSummary(){
  const urgent=state.complaints.filter(c=>openComplaint(c)&&c.priority==='high'),today=state.complaints.filter(c=>localDate(c.createdAt)===state.today),overdue=state.tasks.filter(isOverdue),review=state.tasks.filter(task=>task.status==='reported');
  const attention=[...overdue.sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),...review.filter(r=>!overdue.some(o=>o.id===r.id))];
  const watching=state.tasks.filter(task=>task.watchers?.includes(user.login)&&task.status!=='verified');
  return `<div class="metrics">${metric('seriousToday',urgent.length,'openHigh','warning','problems','urgent')}${metric('newToday',today.length,'receivedAlmaty','','problems','new')}${metric('overdueTasks',overdue.length,'deadlinePassed','danger','tasks','overdue')}${metric('needsReview',review.length,'reportReceived','attention','tasks','review')}</div>${urgent.length?`<div class="lead-notice">${icon('alert')}<div><h3>${t('urgentBanner')}</h3><p>${t('urgentBannerHint')}</p></div>${button(t('viewUrgent'),'drilldown','data-tab="problems" data-filter="urgent"')}</div>`:''}<div class="grid-two"><section class="panel"><div class="panel-header"><div><h2>${t('attention')}</h2><p>${t('attentionHint')}</p></div><span class="count">${attention.length}</span></div>${attention.length?attention.slice(0,5).map(taskRow).join(''):empty(t('noAttention'),t('noAttentionHint'))}${attention.length>5?`<div class="panel-body">${button(t('seeAll'),'drilldown','data-tab="tasks" data-filter="all"',true)}</div>`:''}</section><section class="panel"><div class="panel-header"><div><h2>${t('personalControl')}</h2><p>${t('controlHint')}</p></div><span class="count">${watching.length}</span></div>${watching.length?watching.slice(0,4).map(taskRow).join(''):empty(t('noWatching'),t('watchHint'))}${watching.length?`<div class="panel-body">${button(t('seeAll'),'drilldown','data-tab="tasks" data-filter="watching"',true)}</div>`:''}</section></div><section class="panel section-gap"><div class="panel-header"><div><h2>${t('districtOverview')}</h2><p>${t('districtHint')}</p></div>${button(t('allComplaints'),'drilldown','data-tab="problems" data-filter="all"',true)}</div><div class="panel-body">${districtMap()}</div></section>`;
}
function matchingComplaint(c){const q=prefs.query.trim().toLocaleLowerCase(lang);return (!prefs.districtId||(prefs.districtId==='none'?!c.districtId:c.districtId===prefs.districtId))&&(!prefs.category||c.category===prefs.category)&&(!q||`${c.id} ${c.text} ${c.address}`.toLocaleLowerCase(lang).includes(q));}
function filteredComplaints(){return state.complaints.filter(c=>{
  if(!matchingComplaint(c))return false;
  const linked=state.tasks.filter(task=>task.complaintIds.includes(c.id));
  if(prefs.filter==='open')return openComplaint(c);
  if(prefs.filter==='urgent')return c.priority==='high'&&openComplaint(c);
  if(prefs.filter==='new')return localDate(c.createdAt)===state.today;
  if(prefs.filter==='mine')return linked.some(task=>privileged()?task.createdBy===user.login:task.assignee===user.login)||(!privileged()&&c.assignee===user.login);
  if(prefs.filter==='overdue')return linked.some(isOverdue);
  if(prefs.filter==='review'||prefs.filter==='approval')return linked.some(task=>task.status==='reported');
  if(prefs.filter==='watching')return linked.some(task=>task.status!=='verified'&&task.watchers?.includes(user.login));
  return true;
}).sort((a,b)=>sortOrder.problems==='oldest'?a.createdAt.localeCompare(b.createdAt):sortOrder.problems==='priority'?(Number(b.priority==='high')-Number(a.priority==='high')||b.createdAt.localeCompare(a.createdAt)):b.createdAt.localeCompare(a.createdAt));}
function filterControls(){return `<div class="filter-tabs" role="group" aria-label="${t('savedFilter')}">${['all','mine','overdue','review','watching',...(tab==='problems'?['open','urgent','new']:['open','urgent','new'].includes(prefs.filter)?[prefs.filter]:[])].map(key=>`<button data-action="filter" data-filter="${key}" aria-pressed="${prefs.filter===key}">${t(key)}</button>`).join('')}</div><form id="filters-form" class="toolbar"><input class="search" name="query" type="search" maxlength="300" value="${e(prefs.query)}" placeholder="${t(tab==='tasks'?'searchTasks':'search')}" aria-label="${t('search')}"><select name="districtId" aria-label="${t('district')}"><option value="">${t('allDistricts')}</option>${state.districts.map(d=>`<option value="${e(d.id)}" ${prefs.districtId===d.id?'selected':''}>${e(districtName(d.id))}</option>`).join('')}<option value="none" ${prefs.districtId==='none'?'selected':''}>${t('noDistrict')}</option></select><select name="category" aria-label="${t('category')}"><option value="">${t('allCategories')}</option>${['transport','ecology','social','safety','services','other'].map(key=>`<option value="${key}" ${prefs.category===key?'selected':''}>${t(key)}</option>`).join('')}</select><button class="button small secondary" type="submit">${t('apply')}</button>${button(t('clear'),'clear-filters','',true)}</form>${queueTools()}`;}
function queueTools(){
  const tasks=tab==='tasks',items=tasks?filteredTasks():filteredComplaints();
  const choices=tasks?[['deadline','deadlineFirst'],['newest','newest'],['owner','ownerFirst']]:[['newest','newest'],['oldest','oldest'],['priority','urgentFirst']];
  return `<div class="queue-tools"><span class="caption">${t('queueCount')}: <strong>${items.length}</strong></span><label>${t('sort')}<select data-queue-sort>${choices.map(([value,key])=>`<option value="${value}" ${sortOrder[tab]===value?'selected':''}>${t(key)}</option>`).join('')}</select></label>${button(`${icon('download')}${t('exportQueue')}`,'export-queue',items.length?'':'disabled',true)}</div>`;
}
function exportQueue(){
  const tasks=tab==='tasks',items=tasks?filteredTasks():filteredComplaints();
  const headings=tasks?['№',t('title'),t('owner'),t('deadline'),t('status'),t('expected'),t('complaints'),t('overdue')]:['№',t('created'),t('district'),t('category'),t('address'),t('text'),t('status'),t('priority'),t('owner')];
  const rows=items.map(item=>tasks?[item.id,item.title,item.assignee,item.dueDate,t(item.status),item.expectedResult,item.complaintIds.join(', '),isOverdue(item)?t('overdue'):'']:[item.id,formatDate(item.createdAt,true),districtName(item.districtId),t(item.category),item.address,item.text,t(`complaint_${item.status}`),t(item.priority),item.assignee]);
  downloadCsv(`ascension-${tasks?'tasks':'complaints'}-${state.today}.csv`,[headings,...rows]);
  toast(`${t('queueExported')}: ${items.length}`);
}
function complaintRow(item,selectable=true){const group=state.groups.find(g=>g.complaintIds.includes(item.id));return `<article class="row">${selectable?`<input type="checkbox" class="complaint-check" data-select-complaint="${item.id}" ${selected.has(item.id)?'checked':''} aria-label="${t('choose')} ${t('complaint')} #${item.id}">`:`<span class="row-number">#${item.id}</span>`}<div class="row-body"><div class="chips" style="margin:0 0 7px">${badge(`#${item.id}`,'gray')}${badge(t(item.category))}${item.source==='demo'?badge(t('demo'),'gray'):''}${item.priority==='high'?badge(t('high'),'red'):''}</div><button class="row-link item-text clamp" data-action="complaint-detail" data-id="${item.id}">${e(item.text)}</button><p>${e(districtName(item.districtId))} · ${e(item.address||t('noAddress'))}</p><div class="chips">${complaintStatus(item)}${badge(formatDate(item.createdAt),'gray')}${group?badge(`${t('grouping')}: ${group.title}`,'blue'):''}</div></div><button class="icon-button" data-action="complaint-detail" data-id="${item.id}" aria-label="${t('complaintDetails')} #${item.id}">${icon('arrow')}</button></article>`;}
function suggestions(){const used=new Set(state.groups.flatMap(g=>g.complaintIds)),map=new Map();for(const c of state.complaints){if(!openComplaint(c)||!c.districtId||!c.address?.trim()||used.has(c.id))continue;const key=`${c.districtId}|${c.category}|${c.address.toLocaleLowerCase('ru').trim().replace(/\s+/g,' ')}`;if(!map.has(key))map.set(key,[]);map.get(key).push(c);}return [...map.values()].filter(list=>list.length>=2);}
function renderProblems(){const items=filteredComplaints(),suggested=suggestions();return `<section class="panel"><div class="panel-header"><div><h2>${t('districtOverview')}</h2><p>${t('districtHint')}</p></div><span class="count">${state.complaints.filter(openComplaint).length} ${t('openCount')}</span></div><div class="panel-body">${districtMap()}</div></section><div class="grid-two section-gap"><section><div class="section-gap">${filterControls()}</div><section class="panel"><div class="panel-header"><h2>${t('complaintList')}</h2><span class="count">${items.length}</span></div>${items.length?`${privileged()?`<div class="panel-body" style="padding-bottom:8px"><label class="caption"><input type="checkbox" data-select-all ${items.every(c=>selected.has(c.id))?'checked':''}> ${t('selectAll')}</label></div>`:''}${items.map(c=>complaintRow(c,privileged())).join('')}`:empty(t(state.complaints.length?'noMatches':'noComplaints'),t(state.complaints.length?'noMatchesHint':'noComplaintsHint'),state.complaints.length?button(t('clearFilters'),'clear-filters','',true):`<a class="button secondary" href="/desk.html">${t('desk')}</a>`)}</section><div id="selection-slot">${selectionBar()}</div><p class="caption" style="margin-top:13px">${t('filterSaved')}</p></section><aside class="stack section-gap"><section class="panel"><div class="panel-header"><h2>${t('groupList')}</h2><span class="count">${state.groups.length}</span></div>${state.groups.length?state.groups.map(g=>`<div class="row"><div class="row-body"><h3>${e(g.title)}</h3><p>${g.complaintIds.length} ${t('linkCount')} · ${t('groupingOriginals')}</p><div class="row-actions">${button(t('details'),'group-detail',`data-id="${g.id}"`,true)}${privileged()?button(t('createTask'),'create-task',`data-ids="${g.complaintIds.join(',')}"`):''}</div></div></div>`).join(''):empty(t('noGroups'),t('groupSelection'))}</section><section class="panel"><div class="panel-header"><h2>${t('suggestions')}</h2><span class="count">${suggested.length}</span></div><div class="panel-body"><p class="caption">${t('groupingHint')}</p>${suggested.length?suggested.map(list=>`<div class="insight section-gap"><span class="badge amber">${list.length} ${t('complaints').toLowerCase()}</span><h3>${e(list[0].address)}</h3><p>${e(districtName(list[0].districtId))} · ${t(list[0].category)}</p><p>${t('suggestionReason')}</p>${privileged()?button(t('reviewGroup'),'create-group',`data-ids="${list.map(c=>c.id).join(',')}"`,true):''}</div>`).join(''):`<p class="caption" style="margin-top:17px">${t('noSuggestions')}</p>`}</div></section></aside></div>`;}
function selectionBar(){return selected.size?`<div class="selection-bar"><strong>${t('selected')}: ${selected.size}</strong>${button(t('createTask'),'create-task')}${button(t('group'),'create-group',selected.size<2?'disabled':'')}<button class="text-button" data-action="clear-selection">${t('clearSelection')}</button></div>`:'';}
function filteredTasks(){const q=prefs.query.trim().toLocaleLowerCase(lang);return state.tasks.filter(task=>{
 const linked=task.complaintIds.map(complaintById).filter(Boolean);
 if(prefs.districtId&&!linked.some(c=>prefs.districtId==='none'?!c.districtId:c.districtId===prefs.districtId))return false;
 if(prefs.category&&!linked.some(c=>c.category===prefs.category))return false;
 if(q&&!`${task.id} ${task.title} ${task.expectedResult} ${task.assignee} ${linked.map(c=>`${c.id} ${c.text} ${c.address}`).join(' ')}`.toLocaleLowerCase(lang).includes(q))return false;
 return prefs.filter==='mine'?(privileged()?task.createdBy===user.login:task.assignee===user.login):prefs.filter==='overdue'?isOverdue(task):['review','approval'].includes(prefs.filter)?task.status==='reported':prefs.filter==='watching'?(task.status!=='verified'&&task.watchers?.includes(user.login)):prefs.filter==='open'?task.status!=='verified':prefs.filter==='urgent'?linked.some(c=>c.priority==='high'&&openComplaint(c)):prefs.filter==='new'?localDate(task.createdAt)===state.today:true;
}).sort((a,b)=>sortOrder.tasks==='newest'?b.createdAt.localeCompare(a.createdAt):sortOrder.tasks==='owner'?(a.assignee.localeCompare(b.assignee,lang)||a.dueDate.localeCompare(b.dueDate)):(Number(isOverdue(b))-Number(isOverdue(a))||Number(a.status==='verified')-Number(b.status==='verified')||a.dueDate.localeCompare(b.dueDate)));}
function pendingReport(task){const req=task.reportRequests?.at(-1);return req&&(!task.reports?.length||req.at>task.reports.at(-1).at)&&task.status!=='verified';}
function taskCard(task){const watched=task.watchers?.includes(user.login);return `<article class="panel task-card"><div class="row"><div class="row-body"><div class="chips" style="margin:0 0 10px">${badge(`#${task.id}`,'gray')}${taskStatus(task)}${isOverdue(task)?badge(t('overdue'),'red'):''}<button class="icon-button" data-action="watch" data-id="${task.id}" aria-label="${t(watched?'removeControl':'takeControl')}" aria-pressed="${watched}" title="${t(watched?'removeControl':'takeControl')}">${icon(watched?'check':'watch')}</button></div><h3>${e(task.title)}</h3><div class="task-meta"><span>${t('owner')}: <strong>${e(task.assignee)}</strong></span><span>${t('deadline')}: <strong>${e(formatDate(task.dueDate))}</strong></span></div><p class="expected clamp">${e(task.expectedResult)}</p>${steps(task)}${pendingReport(task)?`<div class="hint">${t('requestPending')}</div>`:''}<div class="row-actions">${button(t('details'),'task-detail',`data-id="${task.id}"`,true)}${task.status==='reported'&&privileged()?button(t('verify'),'task-action',`data-id="${task.id}" data-kind="verify"`):task.status==='assigned'&&canReport(task)?button(t('submitReport'),'task-action',`data-id="${task.id}" data-kind="report"`):''}</div></div></div></article>`;}
function renderTasks(){const items=filteredTasks();return `${filterControls()}${items.length?`<div class="task-grid">${items.map(taskCard).join('')}</div>`:`<section class="panel">${empty(t(state.tasks.length?'noMatches':'noTasks'),t(state.tasks.length?'noMatchesHint':'noTasksHint'),button(t(state.tasks.length?'clearFilters':'seeProblems'),state.tasks.length?'clear-filters':'tab',state.tasks.length?'':'data-tab="problems"',true))}</section>`}<p class="caption" style="margin-top:15px">${t('filterSaved')} ${t('reportsHint')}</p>`;}
function showDialog(title,body,{eyebrow='',onSubmit}={}) {
  dialogTask=null;dirtyDialog=false;
  dialog.innerHTML=`<div class="dialog-head"><div>${eyebrow?`<div class="eyebrow">${e(eyebrow)}</div>`:''}<h2 id="dialog-title">${e(title)}</h2></div><button type="button" class="icon-button" data-action="close-dialog" aria-label="${t('close')}">${icon('close')}</button></div><div class="dialog-content">${body}</div>`;
  if(!dialog.open)dialog.showModal();
  if(onSubmit)$('#action-form',dialog)?.addEventListener('submit',async event=>{
    event.preventDefault();const form=event.currentTarget;if(form.dataset.busy)return;form.dataset.busy='true';const submit=$('button[type=submit]',form),error=$('.form-error',form);if(submit)submit.disabled=true;if(error)error.hidden=true;
    try {await onSubmit(form);}
    catch(err){if(error){error.innerHTML=`${e(err.message)}${err.status===409?`<br><button type="button" class="text-button" data-action="refresh-dialog">${t('staleRefresh')}</button>`:''}`;error.hidden=false;error.scrollIntoView({block:'nearest'});}else onError(err);}
    finally {delete form.dataset.busy;if(submit)submit.disabled=false;}
  });
  setTimeout(()=>{const field=$('input:not([type=checkbox]),textarea,select',dialog);(field||$('.dialog-head button',dialog))?.focus();},20);
}
const formError = () => '<div class="form-error" role="alert" hidden></div>';
const formActions = label => `<div class="dialog-actions">${button(t('cancel'),'close-dialog','',true)}<button class="button" type="submit">${e(label||t('save'))}${icon('check')}</button></div>`;
function attachments(items){return items?.length?`<div class="attachments">${items.map(a=>`<a class="attachment" href="/api/desk/attachments/${Number(a.id)}" target="_blank" rel="noopener"><img src="/api/desk/attachments/${Number(a.id)}" alt="${e(a.name)}" loading="lazy"><span>${e(a.name)}</span></a>`).join('')}</div>`:`<p class="caption">${t('noPhotos')}</p>`;}
function evidenceAttachments(ids){const all=state.complaints.flatMap(c=>c.attachments||[]);return attachments((ids||[]).map(id=>all.find(a=>a.id===id)||{id,name:`${t('attachments')} #${id}`}));}
function residentFeedback(c){if(!c.residentFeedback)return '';const fb=c.residentFeedback;const yes=fb.outcome==='confirmed';return `<div class="hint section-gap">${badge(lang==='kk'?(yes?'Тұрғын растады':'Мәселе шешілмеді'):(yes?'Житель подтвердил':'Проблема осталась'),yes?'':'red')}<p class="item-text" style="margin-top:10px">${e(fb.comment||'')}</p><p class="caption">${e(formatDate(fb.at,true))}</p></div>`;}
function showComplaint(id){const c=complaintById(id);if(!c)return;const linked=state.tasks.filter(task=>task.complaintIds.includes(c.id));showDialog(`${t('complaintDetails')} #${c.id}`,`<div class="chips" style="margin-top:0">${complaintStatus(c)}${badge(t(c.category))}${c.priority==='high'?badge(t('high'),'red'):''}${c.source==='demo'?badge(t('demo'),'gray'):''}</div><p class="item-text section-gap">${e(c.text)}</p><dl class="detail-list"><div><dt>${t('district')}</dt><dd>${e(districtName(c.districtId))}</dd></div><div><dt>${t('address')}</dt><dd>${e(c.address||t('noAddress'))}</dd></div><div><dt>${t('created')}</dt><dd>${e(formatDate(c.createdAt,true))}</dd></div><div><dt>${t('owner')}</dt><dd>${e(c.assignee||t('nobody'))}</dd></div></dl><div class="task-detail-block"><h3>${t('attachments')}</h3>${attachments(c.attachments)}</div>${residentFeedback(c)}${linked.length?`<div class="task-detail-block"><h3>${t('linkedTasks')}</h3>${linked.map(taskRow).join('')}</div>`:''}<details class="task-detail-block"><summary>${t('history')}</summary>${historyList(c.history)}</details><div class="dialog-actions"><a class="button secondary" href="/desk.html?complaint=${c.id}">${t('viewComplaintInDesk')} ↗</a>${privileged()?button(t('createTask'),'create-task',`data-ids="${c.id}"`):''}</div>`,{eyebrow:t('originals')});}
function historyList(history){return history?.length?`<ol class="timeline">${[...history].reverse().map(item=>`<li><time>${e(formatDate(item.at,true))} · ${e(item.actor)}</time>${e(item.text||item.note||item.action||'')}</li>`).join('')}</ol>`:`<p class="caption">${t('noHistory')}</p>`;}
function showTask(id){const task=taskById(id);if(!task)return;const links=task.complaintIds.map(complaintById).filter(Boolean),watched=task.watchers?.includes(user.login),last=task.reports?.at(-1);showDialog(`${t('taskDetails')} #${task.id}`,`<h3 style="font-size:19px">${e(task.title)}</h3><div class="chips">${taskStatus(task)}${isOverdue(task)?badge(t('overdue'),'red'):''}${watched?badge(t('watched')):''}</div><div class="section-gap">${steps(task)}</div><dl class="detail-list"><div><dt>${t('owner')}</dt><dd>${e(task.assignee)}</dd></div><div><dt>${t('deadline')}</dt><dd>${e(formatDate(task.dueDate))}</dd></div></dl><div class="hint"><strong>${t('expected')}</strong><p class="item-text" style="margin-top:7px">${e(task.expectedResult)}</p></div><div class="row-actions">${button(`${icon(watched?'check':'watch')}${t(watched?'removeControl':'takeControl')}`,'watch',`data-id="${task.id}"`,true)}${button(t('copyTaskLink'),'copy-task-link',`data-id="${task.id}"`,true)}${privileged()&&task.status==='assigned'?button(t('requestReport'),'task-action',`data-id="${task.id}" data-kind="request_report"`,true):''}${privileged()&&task.status==='assigned'?button(t('edit'),'task-action',`data-id="${task.id}" data-kind="edit"`,true):''}</div>${task.reportRequests?.length?`<div class="task-detail-block"><h3>${t('reportRequests')}</h3>${task.reportRequests.map(r=>`<div class="hint" style="margin:10px 0"><p class="item-text">${e(r.note)}</p><p class="caption">${e(r.actor)} · ${e(formatDate(r.at,true))}</p></div>`).join('')}</div>`:''}${last?reportDetails(last):''}${task.reports?.length>1?`<details class="task-detail-block"><summary>${t('reports')} (${task.reports.length})</summary>${task.reports.slice(0,-1).reverse().map(reportDetails).join('')}</details>`:''}${task.verification?`<div class="task-detail-block"><h3>${t('verification')}</h3><p class="item-text">${e(task.verification.note)}</p><p class="caption">${t('checkedBy')}: ${e(task.verification.actor)} · ${e(formatDate(task.verification.at,true))}</p></div>`:''}<p class="hint section-gap">${t('noCitizenConfirmation')}</p><div class="task-detail-block"><h3>${t('related')}</h3>${links.map(c=>complaintRow(c,false)).join('')||`<p class="caption">${t('noRelated')}</p>`}</div><details class="task-detail-block"><summary>${t('history')}</summary>${historyList(task.history)}</details><div class="dialog-actions">${task.status==='assigned'&&canReport(task)?button(t('submitReport'),'task-action',`data-id="${task.id}" data-kind="report"`):''}${task.status==='reported'&&privileged()?button(t('verify'),'task-action',`data-id="${task.id}" data-kind="verify"`):''}${task.status!=='assigned'&&privileged()?button(t('return'),'task-action',`data-id="${task.id}" data-kind="return"`,true):''}${button(t('close'),'close-dialog','',true)}</div>`,{eyebrow:`${t('lastUpdated')} · ${formatDate(task.updatedAt,true)}`});dialogTask={id:task.id,mode:'detail'};}
function reportDetails(report){return `<div class="task-detail-block"><h3>${t('report')}</h3><p class="caption">${e(report.actor)} · ${e(formatDate(report.at,true))}</p><p class="item-text" style="margin:12px 0">${e(report.text)}</p>${report.beforeAttachmentIds?.length||report.afterAttachmentIds?.length?`<div class="evidence-columns"><div><h4>${t('before')}</h4>${evidenceAttachments(report.beforeAttachmentIds)}</div><div><h4>${t('after')}</h4>${evidenceAttachments(report.afterAttachmentIds)}</div></div>`:`<p class="caption">${t('noEvidence')}</p>`}</div>`;}
function selectedComplaintIds(el){return (el?.dataset.ids?el.dataset.ids.split(',').map(Number):[...selected]).filter(id=>complaintById(id));}
function defaultDue(){const date=new Date(`${state.today}T12:00:00Z`);date.setUTCDate(date.getUTCDate()+7);return date.toISOString().slice(0,10);}
function taskFields(task={}){return `<label class="field">${t('title')}<input name="title" maxlength="200" required value="${e(task.title||'')}" placeholder="${t('taskTitle')}"></label><div class="field-row"><label class="field">${t('owner')}<select name="assignee" required><option value="">${t('choose')}</option>${state.users.map(u=>`<option value="${e(u.login)}" ${u.login===task.assignee?'selected':''}>${e(u.login)} · ${t(u.role)}</option>`).join('')}</select><span class="caption">${t('assigneeHint')}</span></label><label class="field">${t('deadline')}<input name="dueDate" type="date" min="${state.today}" required value="${e(task.dueDate||defaultDue())}"><span class="caption">${t('dueHint')}</span></label></div><label class="field">${t('expected')}<textarea name="expectedResult" maxlength="2000" required rows="4">${e(task.expectedResult||'')}</textarea><span class="caption">${t('expectedHint')}</span></label>`;}
function createTask(ids){if(!privileged())return toast(t('noAccess'));if(!ids.length){setTab('problems');return;}const requestId=crypto.randomUUID();showDialog(t('createTask'),`<form id="action-form">${formError()}${taskFields({title:ids.length===1?`${t('taskDefault')} #${ids[0]}`:''})}<details><summary class="caption">${t('selectedSource')} (${ids.length})</summary>${ids.map(complaintById).map(c=>complaintPreview(c)).join('')}</details>${formActions(t('createTask'))}</form>`,{eyebrow:t('assignment'),onSubmit:async form=>{const data=Object.fromEntries(new FormData(form));await request('/api/desk/akim/tasks',{method:'POST',body:{...data,complaintIds:ids,requestId}});dialog.close();selected.clear();await savePreferences({filter:'all',query:'',districtId:'',category:''});tab='tasks';history.replaceState(null,'','#tasks');await refresh({silent:true});toast(t('taskCreated'));}});}
function createGroup(ids){if(!privileged())return toast(t('noAccess'));if(ids.length<2)return toast(t('minGroup'));const requestId=crypto.randomUUID();showDialog(t('group'),`<form id="action-form">${formError()}<p class="hint" style="margin-bottom:20px">${t('groupExplain')}</p><label class="field">${t('groupTitle')}<input name="title" maxlength="200" required value="${e(complaintById(ids[0]).address||'')}"></label><div class="panel">${ids.map(complaintById).map(c=>complaintPreview(c)).join('')}</div>${formActions(t('confirm'))}</form>`,{eyebrow:t('grouping'),onSubmit:async form=>{await request('/api/desk/akim/groups',{method:'POST',body:{title:new FormData(form).get('title'),complaintIds:ids,requestId}});dialog.close();selected.clear();await refresh({silent:true});toast(t('groupConfirmed'));}});}
function showGroup(id){const group=groupById(id);if(!group)return;showDialog(group.title,`<p class="hint">${t('groupingOriginals')} · ${group.complaintIds.length} ${t('linkCount')}</p><div class="section-gap">${group.complaintIds.map(complaintById).filter(Boolean).map(c=>complaintRow(c,false)).join('')}</div><div class="dialog-actions">${privileged()?`${button(t('ungroup'),'ungroup',`data-id="${group.id}"`,true)}${button(t('createTask'),'create-task',`data-ids="${group.complaintIds.join(',')}"`)}`:''}${button(t('close'),'close-dialog','',true)}</div>`,{eyebrow:t('generalProblem')});}
function ungroup(id){const group=groupById(id);if(!group)return;showDialog(t('ungroupTitle'),`<form id="action-form">${formError()}<p>${t('ungroupHint')}</p><p class="hint section-gap">${e(group.title)} · ${group.complaintIds.length} ${t('linkCount')}</p>${formActions(t('ungroup'))}</form>`,{onSubmit:async()=>{await request(`/api/desk/akim/groups/${id}`,{method:'PATCH',body:{version:group.version,action:'ungroup'}});dialog.close();await refresh({silent:true});toast(t('ungroupDone'));}});dialogTask={id:group.id,mode:'ungroup',type:'group'};}
function evidenceChoices(task,selectedBefore=[],selectedAfter=[]){const all=task.complaintIds.map(complaintById).filter(Boolean).flatMap(c=>(c.attachments||[]).map(a=>({...a,complaintId:c.id})));return `<div class="evidence-columns">${[['beforeAttachmentIds','before',selectedBefore],['afterAttachmentIds','after',selectedAfter]].map(([name,key,checked])=>`<div><h4>${t(key)}</h4>${all.length?`<div class="attachments">${all.map(a=>`<label class="attachment-choice"><img src="/api/desk/attachments/${a.id}" alt="${e(a.name)}" loading="lazy"><span><input name="${name}" type="checkbox" value="${a.id}" ${checked.includes(a.id)?'checked':''}>${e(a.name)}</span><span class="caption">#${a.complaintId}</span></label>`).join('')}</div>`:`<p class="caption">${t('noPhotos')}</p>`}</div>`).join('')}</div>`;}
function taskAction(id,kind){const task=taskById(id);if(!task)return;const labels={edit:'edit',request_report:'requestReport',report:'submitReport',verify:'verify',return:'return'};let fields='';
  if(kind==='edit')fields=taskFields(task);
  if(kind==='request_report')fields=`<p class="hint">${t('requestReportHint')} ${t('dataNote')}</p><label class="field section-gap">${t('requestNote')}<textarea name="note" maxlength="2000" required rows="4"></textarea></label>`;
  if(kind==='verify')fields=`<p class="hint">${t('verifyHint')}</p>${task.reports?.at(-1)?reportDetails(task.reports.at(-1)):''}<label class="field section-gap">${t('verificationNote')}<textarea name="note" maxlength="2000" required rows="4" placeholder="${t('verificationPlaceholder')}"></textarea></label><p class="caption">${t('noCitizenConfirmation')}</p>`;
  if(kind==='return')fields=`<p class="hint">${t('returnHint')}</p><label class="field section-gap">${t('returnReason')}<textarea name="note" maxlength="2000" required rows="4"></textarea></label><label class="field">${t('newDeadline')}<input type="date" name="dueDate" min="${state.today}" value=""><span class="caption">${t('dueHint')}</span></label>`;
  if(kind==='report')fields=`<p class="hint">${t('reportHint')}</p><label class="field section-gap">${t('reportText')}<textarea name="text" maxlength="5000" required rows="5"></textarea></label><div class="task-detail-block"><h3>${t('chooseEvidence')}</h3><div id="evidence-choices">${evidenceChoices(task)}</div></div><details class="task-detail-block"><summary>${t('uploadPhoto')}</summary><p class="caption" style="margin:10px 0">${t('uploadHint')}</p><div class="field-row"><label class="field">${t('uploadTo')}<select name="uploadComplaint">${task.complaintIds.map(cid=>`<option value="${cid}">#${cid} · ${e(complaintById(cid)?.address||t('noAddress'))}</option>`).join('')}</select></label><label class="field">${t('uploadPhoto')}<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label></div>${button(t('upload'),'upload-photo',`data-id="${task.id}"`,true)}<p id="upload-message" class="caption" role="status" style="margin-top:10px"></p></details>`;
  showDialog(t(labels[kind]),`<p class="caption" style="margin-bottom:17px">#${task.id} · ${e(task.title)}</p><form id="action-form">${formError()}${fields}${formActions(t(labels[kind]))}</form>`,{eyebrow:t('taskDetails'),onSubmit:async form=>{const data=new FormData(form);let body={version:dialogTask?.version||task.version,action:kind};if(kind==='edit')for(const key of ['title','assignee','dueDate','expectedResult'])body[key]=data.get(key);else if(kind==='report'){body.text=data.get('text');body.beforeAttachmentIds=data.getAll('beforeAttachmentIds').map(Number);body.afterAttachmentIds=data.getAll('afterAttachmentIds').map(Number);if(body.beforeAttachmentIds.some(id=>body.afterAttachmentIds.includes(id)))throw new Error(t('reportMustDiffer'));}else{body.note=data.get('note');if(kind==='return'&&data.get('dueDate'))body.dueDate=data.get('dueDate');}await request(`/api/desk/akim/tasks/${id}`,{method:'PATCH',body});dialog.close();await refresh({silent:true});toast(t(kind==='request_report'?'reportRequested':'actionSaved'));showTask(id);}});
  dialogTask={id:task.id,version:task.version,mode:kind,baseline:{title:task.title,assignee:task.assignee,dueDate:task.dueDate,expectedResult:task.expectedResult}};
}
async function uploadPhoto(button){const form=$('#action-form',dialog),input=$('[name=photo]',form),file=input.files[0],message=$('#upload-message');if(!file){message.textContent=t('fileRequired');return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024){message.textContent=t('fileTooBig');return;}button.disabled=true;message.textContent=t('saving');try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error(t('offline')));reader.readAsDataURL(file);});const cid=Number($('[name=uploadComplaint]',form).value);const complaint=await request(`/api/desk/complaints/${cid}/attachments`,{method:'POST',body:{name:file.name,mime:file.type,base64:dataUrl.split(',')[1]}});state.complaints=state.complaints.map(c=>c.id===cid?complaint:c);const values=new FormData(form);$('#evidence-choices').innerHTML=evidenceChoices(taskById(button.dataset.id),values.getAll('beforeAttachmentIds').map(Number),values.getAll('afterAttachmentIds').map(Number));input.value='';message.textContent=t('uploadSuccess');}catch(error){message.textContent=error.message;}finally{button.disabled=false;}}
function reportDateStart(){const date=new Date(`${state.today}T12:00:00Z`);date.setUTCDate(date.getUTCDate()-6);return date.toISOString().slice(0,10);}
function renderMeeting(){return `<section class="panel meeting-controls"><div class="panel-body"><form id="meeting-form" class="meeting-form"><label class="field">${t('rangeFrom')}<input name="from" type="date" required value="${e(meetingReport?.from||reportDateStart())}" max="${state.today}"></label><label class="field">${t('rangeTo')}<input name="to" type="date" required value="${e(meetingReport?.to||state.today)}" max="${state.today}"></label><button class="button" type="submit">${icon('meeting')}${t('generateReport')}</button>${button(t('lastWeek'),'last-week','',true)}</form><p class="caption" style="margin-top:15px">${t('reportDataHint')}</p><div id="meeting-error" class="form-error" role="alert" hidden style="margin-top:15px"></div></div></section><section id="meeting-report" class="panel section-gap">${meetingReport?reportMarkup(meetingReport):empty(t('reportEmpty'),t('reportEmptyHint'))}</section>`;}
function bindMeeting(){const form=$('#meeting-form');form?.addEventListener('submit',async event=>{event.preventDefault();const error=$('#meeting-error'),submit=$('button[type=submit]',form);error.hidden=true;const {from,to}=Object.fromEntries(new FormData(form));if(from>to){error.textContent=t('reportRangeError');error.hidden=false;return;}submit.disabled=true;try{meetingReport=await request(`/api/desk/akim/report?${new URLSearchParams({from,to})}`);$('#meeting-report').innerHTML=reportMarkup(meetingReport);announce(t('weeklyReport'));}catch(err){error.textContent=err.message;error.hidden=false;}finally{submit.disabled=false;}});}
function reportMarkup(report,standalone=false){const taskLine=task=>`<li><strong>#${task.id} ${e(task.title)}</strong> — ${e(task.assignee)}; ${t('deadline')}: ${e(formatDate(task.dueDate))}; ${t('currentStatus')}: ${t(task.status)}. <a href="${standalone?location.origin:''}/akim.html?task=${task.id}#tasks">${t('viewTask')}</a></li>`;const complaintLine=c=>`<li>${c.source==='demo'?`[${t('demo')}] `:''}<a href="${standalone?location.origin:''}/desk.html?complaint=${c.id}">#${c.id}</a> ${e(c.text)} — ${e(districtName(c.districtId))}, ${e(c.address||t('noAddress'))} (${e(formatDate(c.createdAt))})</li>`;const section=(title,items,renderItem)=>`<h3>${title} (${items.length})</h3>${items.length?`<ul>${items.map(renderItem).join('')}</ul>`:`<p class="caption">${t('noPeriod')}</p>`}`;return `<article class="report-paper"><div class="eyebrow">ASCENSION · ${t('cabinet')}</div><h2>${t('weeklyReport')}</h2><p class="report-period">${t('period')}: ${e(formatDate(report.from))} — ${e(formatDate(report.to))}</p><p class="caption">${t('generated')}: ${e(formatDate(report.generatedAt,true))} · ${t('summaryDate')}</p>${standalone?'':`<div class="report-tools section-gap">${button(`${icon('print')}${t('print')}`,'print-report','',true)}${button(`${icon('download')}${t('download')}`,'download-report','',true)}</div>`}<div class="report-kpis">${[['receivedPeriod',report.received],['verifiedPeriod',report.verified],['overdueNow',report.overdue],['reviewNow',report.pendingReview]].map(([label,items])=>`<div>${t(label)}<strong>${items.length}</strong></div>`).join('')}</div><p class="hint">${t('reportDataHint')}</p><h3>${t('neededDecisions')}</h3>${report.overdue.length||report.pendingReview.length?`<ul>${report.overdue.map(task=>`<li><strong>${t('reportActionOverdue')}</strong>: #${task.id} ${e(task.title)} — ${e(task.assignee)}, ${e(formatDate(task.dueDate))}.</li>`).join('')}${report.pendingReview.map(task=>`<li><strong>${t('reportActionReview')}</strong>: #${task.id} ${e(task.title)} — ${e(task.assignee)}.</li>`).join('')}</ul>`:`<p class="caption">${t('noPending')}</p>`}${section(t('receivedPeriod'),report.received,complaintLine)}${section(t('verifiedPeriod'),report.verified,task=>`${taskLine(task).replace('</li>',`<div class="caption">${(task.verificationEvents||[]).map(event=>`${e(formatDate(event.at,true))} · ${e(event.actor)}: ${e(event.text)}`).join('<br>')}</div></li>`)}`)}${section(t('overdueNow'),report.overdue,taskLine)}${section(t('reviewNow'),report.pendingReview,taskLine)}${section(t('recurringPeriod'),report.recurring,group=>`<li><strong>${e(group.title)}</strong> — ${group.complaintIds.map(id=>`<a href="${standalone?location.origin:''}/desk.html?complaint=${id}">#${id}</a>`).join(', ')}</li>`)}<p class="hint section-gap">${t('reportDisclaimer')}</p></article>`;}
function downloadReport(){if(!meetingReport)return;const styles='body{font:15px/1.6 system-ui,sans-serif;color:#21382e;max-width:1000px;margin:40px auto;padding:0 24px}h2{font-size:30px}h3{margin-top:30px}a{color:#2c6149}.caption,.report-period{color:#657368;font-size:13px}.eyebrow{color:#477c58;font-size:12px;letter-spacing:2px}.hint{padding:16px;background:#f0f4e8;border-radius:9px;font-size:13px}.report-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:25px 0}.report-kpis div{border:1px solid #dce3d9;padding:16px;border-radius:9px;font-size:12px}.report-kpis strong{display:block;font-size:30px}.section-gap{margin-top:25px}li{margin:9px 0;white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:600px){.report-kpis{grid-template-columns:repeat(2,1fr)}}@media print{body{margin:0}a{color:inherit}li{break-inside:avoid}h3{break-after:avoid}}';const html=`<!doctype html><html lang="${lang}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src 'none';"><title>${t('weeklyReport')} · ${meetingReport.from} — ${meetingReport.to}</title><style>${styles}</style></head><body>${reportMarkup(meetingReport,true)}</body></html>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`akim-report-${meetingReport.from}-${meetingReport.to}-${lang}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}

async function handleAction(el){const action=el.dataset.action;
  if(action==='language'){lang=el.dataset.lang;localStorage.setItem('akim.lang',lang);if(state){await savePreferences({lang});render();}else showLogin();return;}
  if(action==='reload'){location.reload();return;}
  if(action==='logout'){await request('/api/desk/logout',{method:'POST',body:{}});clearDecisionDrafts();state=null;user=null;selected.clear();meetingReport=null;dialog.close();showLogin();return;}
  if(action==='tab'){setTab(el.dataset.tab);return;}
  if(action==='refresh'){await refresh();return;}
  if(action==='drilldown'){await savePreferences({filter:el.dataset.filter,query:'',districtId:'',category:''});setTab(el.dataset.tab);return;}
  if(action==='district'){await savePreferences({districtId:el.dataset.district,query:'',category:'',filter:'open'});setTab('problems');return;}
  if(action==='filter'){await savePreferences({filter:el.dataset.filter});renderView();return;}
  if(action==='clear-filters'){await savePreferences({filter:'all',query:'',districtId:'',category:''});renderView();return;}
  if(action==='clear-selection'){selected.clear();renderView();return;}
  if(action==='close-dialog'){if(dirtyDialog&&!confirm(t('unsaved')))return;dialog.close();dialogTask=null;return;}
  if(action==='export-queue'){exportQueue();return;}
  if(action==='copy-task-link'){const url=new URL('/akim.html',location.origin);url.searchParams.set('task',el.dataset.id);url.hash='tasks';try{await navigator.clipboard.writeText(url.href);toast(t('linkCopied'));}catch{const field=document.createElement('input');field.readOnly=true;field.value=url.href;field.setAttribute('aria-label',t('copyTaskLink'));el.after(field);field.select();}return;}
  if(action==='complaint-detail'){showComplaint(el.dataset.id);return;}
  if(action==='task-detail'){showTask(el.dataset.id);return;}
  if(action==='task-action'){taskAction(Number(el.dataset.id),el.dataset.kind);return;}
  if(action==='create-task'){createTask(selectedComplaintIds(el));return;}
  if(action==='create-group'){createGroup(selectedComplaintIds(el));return;}
  if(action==='group-detail'){showGroup(Number(el.dataset.id));return;}
  if(action==='ungroup'){ungroup(Number(el.dataset.id));return;}
  if(action==='upload-photo'){await uploadPhoto(el);return;}
  if(action==='watch'){const task=taskById(el.dataset.id);if(!task)return;const detail=dialog.open&&dialogTask?.mode==='detail';el.disabled=true;await request(`/api/desk/akim/tasks/${task.id}`,{method:'PATCH',body:{version:task.version,action:'watch',watch:!task.watchers?.includes(user.login)}});await refresh({silent:true});if(detail)showTask(task.id);return;}
  if(action==='refresh-dialog'){await refreshDialog();return;}
  if(action==='last-week'){const form=$('#meeting-form');form.elements.from.value=reportDateStart();form.elements.to.value=state.today;form.requestSubmit();return;}
  if(action==='print-report'){if(meetingReport)window.print();return;}
  if(action==='download-report'){downloadReport();return;}
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;handleAction(el).catch(error=>{if(dialog.open){const errorEl=$('.form-error',dialog);if(errorEl){errorEl.textContent=error.message;errorEl.hidden=false;}else toast(error.message);}else onError(error);el.disabled=false;});});
document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-queue-sort]')){sortOrder[tab]=el.value;renderView();return;}if(el.matches('[data-select-complaint]')){const id=Number(el.dataset.selectComplaint);if(el.checked)selected.add(id);else selected.delete(id);$('#selection-slot').innerHTML=selectionBar();const all=$('[data-select-all]');if(all)all.checked=filteredComplaints().every(c=>selected.has(c.id));}if(el.matches('[data-select-all]')){for(const c of filteredComplaints()){if(el.checked)selected.add(c.id);else selected.delete(c.id);}renderView();}});
document.addEventListener('submit',event=>{if(event.target.id==='filters-form'){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));savePreferences(values).then(()=>renderView());}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['summary','problems','tasks','decisions','meeting'].includes(next)&&next!==tab){tab=next;render();}});
loginDialog.addEventListener('cancel',event=>event.preventDefault());
dialog.addEventListener('input',event=>{if(event.target.closest('#action-form'))dirtyDialog=true;});
dialog.addEventListener('cancel',event=>{if(dirtyDialog&&!confirm(t('unsaved')))event.preventDefault();});
window.addEventListener('beforeunload',event=>{if(dirtyDialog){event.preventDefault();event.returnValue='';}});
dialog.addEventListener('close',()=>{dialogTask=null;dirtyDialog=false;});
async function init(){try{const session=await request('/api/desk/session');user=session.user;configured=session.configured;if(user)await refresh({silent:true});else showLogin();}catch(error){app.innerHTML=`<div class="boot"><div><p>${e(error.message)}</p>${button(t('retry'),'reload','',true)}</div></div>`;}}
init();
async function refreshDialog(){
  const context=dialogTask,form=$('#action-form',dialog),draft=form?new FormData(form):null;
  await refresh({silent:true});
  if(!context||!draft){toast(t('refreshDone'));return;}
  if(context.type==='group'){if(groupById(context.id))ungroup(context.id);else{dialog.close();toast(t('ungroupDone'));}return;}
  const fresh=taskById(context.id);if(!fresh)return;
  const relevant={report:['assigned'],verify:['reported'],edit:['assigned'],return:['reported','verified'],request_report:['assigned']}[context.mode]||[];
  const draftEntries=[...draft.entries()].filter(([key,value])=>['title','assignee','dueDate','expectedResult','note','text'].includes(key)&&typeof value==='string');
  const preserved=()=>`<details class="hint section-gap" open><summary>${lang==='kk'?'Сақталған мәтініңіз':'Ваш сохранённый черновик'}</summary><div class="item-text" style="margin-top:12px">${draftEntries.map(([key,value])=>`<strong>${e(t(key==='assignee'?'owner':key==='dueDate'?'deadline':key==='expectedResult'?'expected':key))}</strong>\n${e(value)}`).join('\n\n')}</div></details>`;
  if(!relevant.includes(fresh.status)){
    showTask(fresh.id);
    $('.dialog-content',dialog).insertAdjacentHTML('afterbegin',`<div class="hint">${lang==='kk'?'Тапсырма мәртебесі өзгерді. Ағымдағы деректерді тексеріп, қолжетімді әрекетті таңдаңыз.':'Статус поручения изменился. Проверьте актуальные данные и выберите доступное действие.'}</div>${preserved()}`);
    return;
  }
  taskAction(fresh.id,context.mode);
  const nextForm=$('#action-form',dialog);
  if(context.mode==='edit'){
    const changed=[];
    for(const [key,value] of draftEntries){if(Object.hasOwn(context.baseline||{},key)&&value!==context.baseline[key]){nextForm.elements[key].value=value;changed.push(key);}}
    const current=`<div class="hint section-gap"><strong>${lang==='kk'?'Сервердегі ағымдағы деректер':'Актуальные данные на сервере'}</strong><dl class="detail-list"><div><dt>${t('title')}</dt><dd>${e(fresh.title)}</dd></div><div><dt>${t('owner')}</dt><dd>${e(fresh.assignee)}</dd></div><div><dt>${t('deadline')}</dt><dd>${e(formatDate(fresh.dueDate))}</dd></div><div><dt>${t('expected')}</dt><dd>${e(fresh.expectedResult)}</dd></div></dl><p>${lang==='kk'?'Сіз өзгерткен өрістер нысанда сақталды. Сақтамас бұрын оларды ағымдағы деректермен салыстырыңыз.':'Изменённые вами поля сохранены в форме. Сравните их с актуальными данными перед сохранением.'}</p></div>`;
    nextForm.insertAdjacentHTML('afterbegin',current+preserved());
  }else{
    for(const key of ['note','text',...(context.mode==='return'?['dueDate']:[])])if(nextForm.elements[key]&&draft.has(key))nextForm.elements[key].value=draft.get(key);
    for(const name of ['beforeAttachmentIds','afterAttachmentIds'])for(const input of nextForm.querySelectorAll(`input[name="${name}"]`))input.checked=draft.getAll(name).includes(input.value);
    nextForm.insertAdjacentHTML('afterbegin',`<p class="hint" style="margin-bottom:20px">${lang==='kk'?'Деректер жаңартылды. Мәтініңіз сақталды. Сақтамас бұрын ағымдағы есеп пен дәлелдерді қайта тексеріңіз.':'Данные обновлены. Ваш текст сохранён. Перед сохранением заново проверьте актуальный отчёт и подтверждения.'}</p>`);
  }
  announce(t('refreshDone'));
}
function complaintPreview(item){return `<article class="row"><span class="row-number">#${item.id}</span><div class="row-body"><h3 class="item-text">${e(item.text)}</h3><p>${e(districtName(item.districtId))} · ${e(item.address||t('noAddress'))}</p><div class="chips">${badge(t(item.category))}${complaintStatus(item)}</div><p><a href="/desk.html?complaint=${item.id}" target="_blank" rel="noopener">${t('viewComplaintInDesk')} ↗</a></p></div></article>`;}
